-- AI Usage Note
-- Generated by Claude (Claude Code): this migration.
-- How it was verified: applied with prisma migrate dev to a local database; each constraint was shown to reject a violating row and accept a valid one in a rolled-back transaction; a second prisma migrate dev --create-only produced an empty migration.
-- Reviewed by: Vlad-Re
--
-- Invariants from docs/architecture/data-model.md §3 that the Prisma schema cannot express.
-- Prisma does not manage these objects; they are not in schema.prisma.

-- Usernames are unique regardless of case.
CREATE UNIQUE INDEX "profiles_username_lower_key" ON "profiles" (lower("username"));

-- One active application per user and session. `removed`, `withdrawn`, `no_match` and `cancelled` stay outside.
CREATE UNIQUE INDEX "applications_user_id_session_id_active_key"
    ON "applications" ("user_id", "session_id")
    WHERE "status" IN ('in_pool', 'paired', 'paused');

-- CREATE UNIQUE INDEX ... ON report_cases (target_account_id, target_listing_id) WHERE status = 'open';

-- One open case per report target (an account or a listing).
CREATE UNIQUE INDEX "report_cases_open_target_account_key"
    ON "report_cases" ("target_account_id")
    WHERE "status" = 'open' AND "target_account_id" IS NOT NULL;

CREATE UNIQUE INDEX "report_cases_open_target_listing_key"
    ON "report_cases" ("target_listing_id")
    WHERE "status" = 'open' AND "target_listing_id" IS NOT NULL;

-- Exactly one target in a report case, and it matches target_type.
ALTER TABLE "report_cases" ADD CONSTRAINT "report_cases_one_target_check" CHECK (
    ("target_type" = 'account' AND "target_account_id" IS NOT NULL AND "target_listing_id" IS NULL)
    OR ("target_type" = 'listing' AND "target_listing_id" IS NOT NULL AND "target_account_id" IS NULL)
);

-- A match joins two different applications.
ALTER TABLE "matches" ADD CONSTRAINT "matches_different_applications_check"
    CHECK ("application_a_id" <> "application_b_id");

-- An active account has a date of birth. The value is encrypted, so the database cannot check the age (SAFE-001); the identity service does.
ALTER TABLE "accounts" ADD CONSTRAINT "accounts_active_has_date_of_birth_check"
    CHECK ("status" <> 'active' OR "date_of_birth" IS NOT NULL);
